python3 -c 'exec("import json, os, sys
HOOK = ("hooks", "project_ground_hook.py")
MESSAGE = ("Orch Dork was reinstalled while this task was open, so its hooks are gone. "
           "Start a new task to keep working.")
def hook(root):
    return os.path.join(root, *HOOK)
def installed(parent):
    found = []
    for name in sorted(os.listdir(parent)):
        root = os.path.join(parent, name)
        try:
            with open(os.path.join(root, ".codex-plugin", "plugin.json"), encoding="utf-8") as handle:
                version = json.load(handle).get("version")
        except (OSError, ValueError, AttributeError):
            continue
        if version == name and os.path.isfile(hook(root)):
            found.append(root)
    return found
given = sys.argv[1] if len(sys.argv) > 1 else ""
root = given if given and not given.startswith("$") else os.environ.get("PLUGIN_ROOT", "")
if root and os.path.isfile(hook(root)):
    os.execv(sys.executable, [sys.executable, hook(root)])
data = sys.stdin.buffer.read()
try:
    event = json.loads(data.decode("utf-8") or "{}").get("hook_event_name")
except (ValueError, UnicodeDecodeError, AttributeError):
    event = None
try:
    roots = installed(os.path.dirname(os.path.normpath(root))) if root else []
except OSError:
    roots = []
if event in ("SessionStart", "PreToolUse", "PostToolUse") and len(roots) == 1:
    import subprocess
    done = subprocess.run([sys.executable, hook(roots[0])], input=data, stdout=subprocess.PIPE,
                          env=dict(os.environ, PLUGIN_ROOT=roots[0]))
    sys.stdout.buffer.write(done.stdout)
    sys.exit(done.returncode)
if event == "PreToolUse":
    output = {"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny",
                                     "permissionDecisionReason": MESSAGE}}
elif event == "SessionStart":
    output = {"continue": True, "systemMessage": MESSAGE}
else:
    output = {"continue": True}
sys.stdout.write(json.dumps(output, sort_keys=True, separators=(",", ":")) + "\n")
")' "${PLUGIN_ROOT}"

